describe('Mobile Navigation Collapse to Hamburger Menu', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should collapse navigation into hamburger menu on mobile viewport', () => {
    // Set viewport to mobile size
    cy.viewport('iphone-x');

    // Verify navigation links are visible in desktop view
    cy.get('[data-testid="nav-link-home"]').should('be.visible');
    cy.get('[data-testid="nav-link-about"]').should('be.visible');
    cy.get('[data-testid="nav-link-services"]').should('be.visible');

    // Verify hamburger menu button is visible
    cy.get('[data-testid="hamburger-menu-button"]').should('be.visible');

    // Click hamburger menu button
    cy.get('[data-testid="hamburger-menu-button"]').click();

    // Verify navigation menu is now open
    cy.get('[data-testid="mobile-nav-menu"]').should('be.visible');

    // Verify navigation links are inside the mobile menu
    cy.get('[data-testid="mobile-nav-link-home"]').should('be.visible');
    cy.get('[data-testid="mobile-nav-link-about"]').should('be.visible');
    cy.get('[data-testid="mobile-nav-link-services"]').should('be.visible');

    // Verify menu has a close button
    cy.get('[data-testid="close-mobile-menu-button"]').should('be.visible');

    // Click close button
    cy.get('[data-testid="close-mobile-menu-button"]').click();

    // Verify navigation menu is closed
    cy.get('[data-testid="mobile-nav-menu"]').should('not.exist');
  });

  it('should handle navigation menu interaction and close on outside click', () => {
    // Set viewport to mobile size
    cy.viewport('iphone-12');

    // Open hamburger menu
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-nav-menu"]').should('be.visible');

    // Click on a navigation link
    cy.get('[data-testid="mobile-nav-link-about"]').click();

    // Verify navigation link is active
    cy.get('[data-testid="mobile-nav-link-about"]').should('have.class', 'active');

    // Verify menu closes after link click
    cy.get('[data-testid="mobile-nav-menu"]').should('not.exist');

    // Open menu again
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-nav-menu"]').should('be.visible');

    // Click outside the menu to close it
    cy.get('[data-testid="nav-link-home"]').click();

    // Verify menu closes on outside click
    cy.get('[data-testid="mobile-nav-menu"]').should('not.exist');

    // Verify hamburger button is still functional
    cy.get('[data-testid="hamburger-menu-button"]').should('be.visible');
  });
});
